import 'dart:io';

const catalogMigrationHeader =
    '-- Generated by tools/export_mcp_catalog.sh; do not edit.';

String catalogMigrationPath(
  DateTime now, {
  String directory = 'supabase/migrations',
}) {
  final utc = now.toUtc();
  String pad(int value, int width) => value.toString().padLeft(width, '0');
  final timestamp =
      '${pad(utc.year, 4)}${pad(utc.month, 2)}${pad(utc.day, 2)}'
      '${pad(utc.hour, 2)}${pad(utc.minute, 2)}${pad(utc.second, 2)}';
  return '$directory/${timestamp}_mcp_catalog.sql';
}

File latestCatalogMigration({String directory = 'supabase/migrations'}) {
  final migrations =
      Directory(directory)
          .listSync()
          .whereType<File>()
          .where((file) => RegExp(r'/\d{14}_[^/]+\.sql$').hasMatch(file.path))
          .where(
            (file) =>
                file.readAsStringSync().startsWith('$catalogMigrationHeader\n'),
          )
          .toList()
        ..sort((a, b) => a.path.compareTo(b.path));
  if (migrations.isEmpty) {
    throw StateError('No generated MCP catalog migration found in $directory');
  }
  return migrations.last;
}

void writeCatalogMigration(File file, String sql) {
  if (file.existsSync()) {
    if (file.readAsStringSync() == sql) return;
    throw StateError('Refusing to overwrite existing migration: ${file.path}');
  }
  file.writeAsStringSync(sql);
}
